CREATE OR REPLACE FUNCTION get_order_total(p_order_id INT)
RETURNS NUMERIC
LANGUAGE plpgsql
AS $$
DECLARE
  v_total NUMERIC;
BEGIN
  SELECT SUM(total) INTO v_total
  FROM order_items
  WHERE order_id = p_order_id;

  IF v_total IS NULL THEN
    v_total := 0;
  END IF;

  RETURN v_total;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'Failed to get order total: %', SQLERRM;
    RETURN 0;
END;
$$;
